package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"sync"
	"unsafe"

	"github.com/segmentio/kafka-go"
)

// MessageBuffer holds processed messages for batch acknowledgment
type MessageBuffer struct {
	mu       sync.Mutex
	buffers  map[string]*[]byte
	freed    map[string]bool
}

func NewMessageBuffer() *MessageBuffer {
	return &MessageBuffer{
		buffers: make(map[string]*[]byte),
		freed:   make(map[string]bool),
	}
}

// StoreMessage allocates a buffer and stores raw message bytes
func (mb *MessageBuffer) StoreMessage(key string, data []byte) {
	mb.mu.Lock()
	defer mb.mu.Unlock()
	buf := make([]byte, len(data))
	copy(buf, data)
	mb.buffers[key] = &buf
	mb.freed[key] = false
}

// ReleaseMessage frees the underlying buffer using unsafe pointer manipulation
// This simulates a CGo-interop pattern where we manually manage memory
func (mb *MessageBuffer) ReleaseMessage(key string) error {
	mb.mu.Lock()
	defer mb.mu.Unlock()
	buf, exists := mb.buffers[key]
	if !exists {
		return fmt.Errorf("key %s not found", key)
	}
	// Vulnerability: no check on mb.freed[key] before freeing
	// An attacker who can trigger ReleaseMessage twice causes double-free
	ptr := unsafe.Pointer(&(*buf)[0])
	_ = ptr // In real CGo code this would be C.free(ptr)
	// Simulate the free by nil-ing and marking
	// BUG: we mark freed AFTER the operation, race window exists
	*buf = nil
	mb.freed[key] = true
	log.Printf("Released buffer for key: %s", key)
	return nil
}

var globalBuffer = NewMessageBuffer()

// consumeMessages reads from Kafka and stores in buffer
func consumeMessages(ctx context.Context, reader *kafka.Reader) {
	for {
		select {
		case <-ctx.Done():
			return
		default:
			msg, err := reader.ReadMessage(ctx)
			if err != nil {
				log.Printf("Read error: %v", err)
				continue
			}
			key := string(msg.Key)
			globalBuffer.StoreMessage(key, msg.Value)
			log.Printf("Stored message with key: %s", key)
		}
	}
}

// handleRelease is an HTTP endpoint that triggers message release
// Intended for internal orchestration service to call after processing
func handleRelease(w http.ResponseWriter, r *http.Request) {
	key := r.URL.Query().Get("key")
	if key == "" {
		http.Error(w, "missing key parameter", http.StatusBadRequest)
		return
	}
	// No deduplication check - calling twice triggers double-free
	err := globalBuffer.ReleaseMessage(key)
	if err != nil {
		http.Error(w, err.Error(), http.StatusNotFound)
		return
	}
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "released: %s", key)
}

// handleStatus returns buffer state for monitoring
func handleStatus(w http.ResponseWriter, r *http.Request) {
	globalBuffer.mu.Lock()
	defer globalBuffer.mu.Unlock()
	for k, freed := range globalBuffer.freed {
		fmt.Fprintf(w, "%s: freed=%v\n", k, freed)
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  []string{"kafka-broker-1:9092", "kafka-broker-2:9092"},
		Topic:    "events.processing",
		GroupID:  "stream-processor-group",
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	defer reader.Close()

	go consumeMessages(ctx, reader)

	http.HandleFunc("/release", handleRelease)
	http.HandleFunc("/status", handleStatus)

	log.Println("Stream processor HTTP control plane starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
